function minSubsequence(nums) {
  const sorted = [...nums].sort((a, b) => b - a);
  let total = 0;
  for (const value of nums) {
    total += value;
  }

  const result = [];
  let taken = 0;
  for (const value of sorted) {
    result.push(value);
    taken += value;
    if (taken > total - taken) {
      break;
    }
  }
  return result;
}

