function minSubsequence(nums) {
  const n = nums.length;
  const total = nums.reduce((s, v) => s + v, 0);
  if (n > 16) {
    // Too many subsets: take values from the top bucket down instead.
    const count = new Array(101).fill(0);
    for (const v of nums) count[v]++;
    const picked = [];
    let sum = 0;
    for (let v = 100; v >= 1 && sum <= total - sum; v--)
      while (count[v] > 0 && sum <= total - sum) { picked.push(v); sum += v; count[v]--; }
    return picked;
  }
  let bestMask = -1, bestCount = Infinity, bestSum = -1;
  for (let mask = 0; mask < (1 << n); mask++) {
    let count = 0, sum = 0;
    for (let i = 0; i < n; i++) if (mask & (1 << i)) { count++; sum += nums[i]; }
    if (sum <= total - sum) continue;
    if (count < bestCount || (count === bestCount && sum > bestSum)) { bestMask = mask; bestCount = count; bestSum = sum; }
  }
  const picked = [];
  for (let i = 0; i < n; i++) if (bestMask & (1 << i)) picked.push(nums[i]);
  return picked.sort((a, b) => b - a);
}

